import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cpp_source = r"""
#include <torch/extension.h>

torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);
"""

_cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int64_t M,
    int64_t K
) {
    const int row = blockIdx.x;
    const int tid = threadIdx.x;

    if (row >= M) {
        return;
    }

    float sum = 0.0f;
    const int64_t row_offset = static_cast<int64_t>(row) * K;

    for (int64_t k = tid; k < K; k += blockDim.x) {
        sum += A[row_offset + k] * B[k];
    }

    __shared__ float reduction[256];
    reduction[tid] = sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            reduction[tid] += reduction[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        C[row] = reduction[0];
    }
}

torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.dim() == 2, "A must have shape (M, K)");
    TORCH_CHECK(B.dim() == 2, "B must have shape (K, 1)");
    TORCH_CHECK(A.size(1) == B.size(0), "Incompatible matrix dimensions");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K, 1)");
    TORCH_CHECK(A.device() == B.device(), "A and B must be on the same CUDA device");

    auto A_contiguous = A.contiguous();
    auto B_contiguous = B.contiguous();

    const int64_t M = A_contiguous.size(0);
    const int64_t K = A_contiguous.size(1);

    auto C = torch::empty({M, 1}, A_contiguous.options());

    c10::cuda::CUDAGuard device_guard(A_contiguous.device());
    cudaStream_t stream = at::cuda::getCurrentCUDAStream(
        A_contiguous.get_device()
    ).stream();

    constexpr int threads = 256;
    const dim3 grid(static_cast<unsigned int>(M));
    const dim3 block(threads);

    matvec_kernel<<<grid, block, 0, stream>>>(
        A_contiguous.data_ptr<float>(),
        B_contiguous.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
}
"""

_matvec_cuda = load_inline(
    name="matvec_cuda_extension",
    cpp_sources=_cpp_source,
    cuda_sources=_cuda_source,
    functions=["matvec_cuda"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _matvec_cuda.matvec_cuda(A, B)

